def _cart_position(event, item, membership=None, **kwargs):
    return CartPosition(event=event, item=item, price=Decimal('23.00'), used_membership=membership, **kwargs)


@pytest.mark.django_db
def test_validate_memberships_in_order_valid(event, customer, membership, requiring_ticket):
    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)


@pytest.mark.django_db
def test_validate_memberships_in_order_locked(event, customer, membership, requiring_ticket):
    with transaction.atomic():
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event, lock=True)


@pytest.mark.django_db
def test_validate_memberships_in_order_membership_required(event, customer, requiring_ticket):
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket)], event)
    assert 'membership' in str(excinfo.value)


@pytest.mark.django_db
def test_validate_memberships_in_order_no_customer(event, membership, requiring_ticket):
    with pytest.raises(ValidationError):
        validate_memberships_in_order(None, [_cart_position(event, requiring_ticket, membership)], event)


@pytest.mark.django_db
def test_validate_memberships_in_order_other_customer(event, membership, requiring_ticket):
    other = event.organizer.customers.create(email="jane@example.org")
    with pytest.raises(ValidationError):
        validate_memberships_in_order(other, [_cart_position(event, requiring_ticket, membership)], event)


@pytest.mark.django_db
def test_validate_memberships_in_order_wrong_testmode(event, customer, membership, requiring_ticket):
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event,
                                      testmode=True)


@pytest.mark.django_db
def test_validate_memberships_in_order_wrong_type(event, customer, membership, requiring_ticket):
    other_type = event.organizer.membership_types.create(name="Other pass")
    membership.membership_type = other_type
    membership.save()
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)


@pytest.mark.django_db
def test_validate_memberships_in_order_not_valid_for_date(event, customer, membership, requiring_ticket):
    membership.date_start = datetime(2021, 5, 1, 0, 0, 0, 0, tzinfo=TZ)
    membership.date_end = datetime(2021, 5, 30, 23, 59, 59, 999999, tzinfo=TZ)
    membership.save()
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)


@pytest.mark.django_db
def test_validate_memberships_in_order_not_valid_for_date_but_not_chosen_yet(event, customer, membership,
                                                                             requiring_ticket):
    membership.date_start = datetime(2050, 5, 1, 0, 0, 0, 0, tzinfo=TZ)
    membership.date_end = datetime(2050, 5, 30, 23, 59, 59, 999999, tzinfo=TZ)
    membership.save()
    position = _cart_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [position], event)
    validate_memberships_in_order(customer, [position], event, valid_from_not_chosen=True)


@pytest.mark.django_db
def test_validate_memberships_in_order_max_usages(event, customer, membership, membership_type, requiring_ticket):
    membership_type.max_usages = 1
    membership_type.save()
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [
            _cart_position(event, requiring_ticket, membership),
            _cart_position(event, requiring_ticket, membership),
        ], event)


@pytest.mark.django_db
def test_validate_memberships_in_order_max_usages_existing(event, customer, membership, membership_type,
                                                           requiring_ticket):
    membership_type.max_usages = 1
    membership_type.save()
    with scope(organizer=event.organizer):
        order = Order.objects.create(
            code='FOO', event=event, email='dummy@example.org', status=Order.STATUS_PENDING,
            datetime=now(), expires=now(), total=Decimal('23.00'), customer=customer,
        )
        OrderPosition.objects.create(
            order=order, item=requiring_ticket, price=Decimal('23.00'), used_membership=membership,
        )
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event,
                                  ignored_order=order)


@pytest.mark.django_db
def test_validate_memberships_in_order_not_transferable(event, customer, membership, membership_type,
                                                        requiring_ticket):
    membership.attendee_name_parts = {'_scheme': 'full', 'full_name': 'John Doe'}
    membership.save()
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_cart_position(
            event, requiring_ticket, membership, attendee_name_parts={'_scheme': 'full', 'full_name': 'Mark Fisher'}
        )], event)
    validate_memberships_in_order(customer, [_cart_position(
        event, requiring_ticket, membership, attendee_name_parts={'_scheme': 'full', 'full_name': 'John Doe'}
    )], event)


@pytest.mark.django_db
def test_validate_memberships_in_order_transferable(event, customer, membership, membership_type, requiring_ticket):
    membership_type.transferable = True
    membership_type.save()
    membership.attendee_name_parts = {'_scheme': 'full', 'full_name': 'John Doe'}
    membership.save()
    validate_memberships_in_order(customer, [_cart_position(
        event, requiring_ticket, membership, attendee_name_parts={'_scheme': 'full', 'full_name': 'Mark Fisher'}
    )], event)


@pytest.mark.django_db
def test_validate_memberships_in_order_parallel_usage(event, customer, membership, requiring_ticket):
    positions = [_cart_position(event, requiring_ticket, membership) for _ in range(2)]
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, positions, event)


@pytest.mark.django_db
def test_validate_memberships_in_order_parallel_usage_allowed(event, customer, membership, membership_type,
                                                              requiring_ticket):
    membership_type.allow_parallel_usage = True
    membership_type.save()
    positions = [_cart_position(event, requiring_ticket, membership) for _ in range(2)]
    validate_memberships_in_order(customer, positions, event)


@pytest.mark.django_db
def test_validate_memberships_in_order_membership_forbidden(event, customer, membership, granting_ticket):
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_cart_position(event, granting_ticket, membership)], event)
